  (* [comment removed for export] *)
  Lemma gc_classes_run : forall (q : nat) regs M c,
    gcl_inv regs c -> (0 <= c)%Z -> (c + Z.of_nat q = 10)%Z -> out_gc M -> mem_grows mem0 M ->
    exists regs' M',
